// Verus solution for 3-cycle swap on a mutable Vec<i32>.
//
// Spec: given distinct valid indices h, i, j,
// after swap3:
//   a[h] == old(a[i])
//   a[i] == old(a[j])
//   a[j] == old(a[h])
// and all other positions unchanged; length unchanged.

use vstd::prelude::*;

verus! {

fn swap3(a: &mut Vec<i32>, h: usize, i: usize, j: usize)
    requires
        h < old(a).len(),
        i < old(a).len(),
        j < old(a).len(),
        h != i,
        i != j,
        h != j,
    ensures
        a.len() == old(a).len(),
        a[h] == old(a)[i],
        a[i] == old(a)[j],
        a[j] == old(a)[h],
        forall|k: usize|
            k < a.len() && k != h && k != i && k != j ==> a[k] == old(a)[k],
{
    // Cache the original three values.
    let ah = a[h];
    let ai = a[i];
    let aj = a[j];

    // Perform the 3-cycle:
    // h <- old(i), i <- old(j), j <- old(h)
    a[h] = ai;
    a[i] = aj;
    a[j] = ah;
}

} // verus!